<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thiebapower · Location</title><link rel="stylesheet" href="/style.css"><main><h1>THIEBAPOWER</h1><p>Location de batterie externe</p><section><h2>Votre location</h2><p><?=number_format($prices['rental_fee'])?> FCFA pour <?= (int)$prices['duration_minutes'] ?> minutes · caution dès <?=number_format($prices['default_deposit'])?> FCFA</p><p>Dépassement : <?= (int)$prices['late_percent'] ?> % de la caution par heure entamée, dans la limite de la caution.</p><form method="post" action="/rentals"><label>Batterie<select name="battery_id" required><?php foreach($batteries as $b):?><option value="<?= (int)$b['id'] ?>"><?=htmlspecialchars($b['serial'])?> · caution <?=number_format($b['deposit_override']??$prices['default_deposit'])?> FCFA</option><?php endforeach ?></select></label><label>Nom<input name="name" required></label><label>Email<input name="email" type="email" required></label><label>Téléphone<input name="phone" type="tel" required></label><button <?= !$batteries?'disabled':'' ?>>Continuer vers le paiement</button></form></section></main></html>